<?php $title='Version History'; ?>
<div class="page-head"><div><span class="eyebrow">CONFIGURATION LIFECYCLE</span><h1>Version History</h1><p><?= e($environment['name'] ?? 'Chưa chọn môi trường') ?> · bản phát hành được giữ bất biến.</p></div></div>
<?php if(!$isTestEnvironment): ?><div class="notice info">Môi trường phát hành chỉ xem. Có thể so sánh lịch sử nhưng không tạo, sửa, rollback hoặc phát hành cấu hình tại đây.</div><?php endif; ?>
<div class="two-col"><section class="panel"><div class="panel-head"><div><h2><?= $isTestEnvironment?'Bản nháp Staging':'Trạng thái phát hành' ?></h2><p><?= $isTestEnvironment?'Thay đổi được lưu trong môi trường thử nghiệm. Phát hành bản nháp tại mục Features.':'Cấu hình phát hành được giữ bất biến trong giao diện này.' ?></p></div></div><?php if($isTestEnvironment): ?><form method="post" action="<?= e(url('versions/draft')) ?>" class="inline-form"><?= csrf_field() ?><input name="reason" placeholder="Lý do thay đổi"><button class="button primary" type="submit">Tạo bản nháp mới</button></form><?php if($draft): ?><div class="notice info">Bản nháp hiện tại: v<?= (int)$draft['version_number'] ?> · <?= e($draft['change_reason'] ?? 'Chưa có lý do') ?></div><?php else: ?><p class="empty">Chưa có bản nháp. Tạo bản nháp để bắt đầu thay đổi.</p><?php endif; ?><?php else: ?><p class="muted">Bản phát hành hiện tại: v<?= (int)($current['version_number'] ?? 0) ?></p><?php endif; ?></section>
<section class="panel"><div class="panel-head"><div><h2>So sánh phiên bản</h2><p>Xem thay đổi giữa các snapshot; thao tác này không sửa cấu hình.</p></div></div><form method="post" action="<?= e(url('versions/compare')) ?>" class="form-grid"><?= csrf_field() ?><label>Từ<select name="left_version_id" required><?php foreach($versions as $version): ?><option value="<?= (int)$version['id'] ?>">v<?= (int)$version['version_number'] ?> · <?= e($version['status']) ?></option><?php endforeach; ?></select></label><label>Đến<select name="right_version_id" required><?php foreach($versions as $version): ?><option value="<?= (int)$version['id'] ?>">v<?= (int)$version['version_number'] ?> · <?= e($version['status']) ?></option><?php endforeach; ?></select></label><button class="button" type="submit">So sánh</button></form></section></div>
<section class="panel"><div class="panel-head"><div><h2>Lịch sử phiên bản</h2><p><?= count($versions) ?> phiên bản</p></div></div><?php if(!$versions): ?><p class="empty">Chưa có phiên bản nào.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Phiên bản</th><th>Trạng thái</th><th>Lý do / nguồn</th><th>Người phát hành</th><th>Thời điểm</th><th>Hành động</th></tr></thead><tbody><?php foreach($versions as $version): ?><tr><td><strong>v<?= (int)$version['version_number'] ?></strong><?= !empty($version['rollback_of_id'])?' <span class="pill amber">Rollback</span>':'' ?></td><td><span class="pill <?= $version['status']==='published'?'green':'amber' ?>"><?= e($version['status']) ?></span><?= (int)($current['id']??0)===(int)$version['id']?' <small>Current</small>':'' ?></td><td><?= e($version['change_reason'] ?? '—') ?></td><td><?= $version['status']==='published'?e($version['published_by_name'] ?? '—'):'—' ?></td><td><?= e($version['published_at'] ?? $version['created_at']) ?></td><td><?php if($isTestEnvironment && $version['status']==='published'): ?><form method="post" action="<?= e(url('versions/rollback')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="version_id" value="<?= (int)$version['id'] ?>"><input name="reason" required placeholder="Lý do rollback"><button class="button small" type="submit">Khôi phục</button></form><?php elseif($version['status']==='draft'): ?>Bản nháp<?php else: ?>Chỉ xem<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
